    source_corpus_fingerprint: ?[]u8 = null,
    rubric_fingerprint: ?[]u8 = null,
    replay_policy_fingerprint: ?[]u8 = null,
    grader_authority_fingerprint: ?[]u8 = null,
    minimum_aggregate: f64 = 0,
    zero_critical_violations: bool = true,
