            "{\"schema\":\"hylo-trial/v1\",\"sealing\":{\"source_selection_receipt\":{\"schema\":\"hylo-source-selection-receipt/v1\",\"source_owner_attestation\":{\"schema\":\"hylo-source-selection-attestation-subject/v1\",\"producer\":{\"public_key_base64\":\"",
            public_key,
