    );
    defer std.testing.allocator.free(unrelated_payload);
    try testExpectPublicationRejectedUnchanged(
        std.testing.allocator,
        repo,
        store,
        unrelated_payload,
        error.PublicationCommitNotDescendant,
    );
}

